previewCss:
.darma-loader-darma-b15-paint-roller { --accent: var(--loader-color, #2563eb); --accent-2: var(--loader-secondary-color, #93c5fd); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .62); position: relative; }
.darma-loader-darma-b15-paint-roller .darma-loader-darma-b15-paint-roller__wall { position: absolute; inset: 0; border-radius: 7px; background: color-mix(in srgb, var(--accent) 12%, transparent); }
.darma-loader-darma-b15-paint-roller .darma-loader-darma-b15-paint-roller__stripe { position: absolute; left: 6%; top: 40%; height: 28%; width: 0; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: darma-loader-darma-b15-paint-roller-paint-fill calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b15-paint-roller .darma-loader-darma-b15-paint-roller__roller { position: absolute; top: 36%; left: 6%; width: 15%; height: 36%; border-radius: 4px; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-paint-roller-paint-move calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b15-paint-roller .darma-loader-darma-b15-paint-roller__roller::after { content: ''; position: absolute; left: 38%; bottom: 96%; width: 16%; height: 62%; border-radius: 2px; background: #94a3b8; }
@keyframes darma-loader-darma-b15-paint-roller-paint-fill { 0% { width: 0; opacity: 1; } 55%, 70% { width: 88%; opacity: 1; } 94%, 100% { width: 88%; opacity: 0; } }
@keyframes darma-loader-darma-b15-paint-roller-paint-move { 0% { left: 6%; } 55%, 70% { left: 79%; } 100% { left: 6%; } }

